<?php
declare(strict_types=1);
ini_set('session.save_path',__DIR__.'/../includes/runtime');require_once __DIR__.'/../includes/db.php';
$db=db();$failed=false;
$sql="SELECT g.grade_number,COUNT(*) lessons,SUM(CHAR_LENGTH(COALESCE(CASE WHEN s.name_en LIKE '%Second Language Tamil%' THEN l.short_notes_ta WHEN s.name_en LIKE '%Second Language Sinhala%' THEN l.short_notes_si WHEN l.medium='Sinhala' THEN l.short_notes_si WHEN l.medium='Tamil' THEN l.short_notes_ta ELSE l.short_notes_en END,''))>=350) notes_ready,SUM(COALESCE(x.questions,0)=5) challenges_ready FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id LEFT JOIN (SELECT q.lesson_id,COUNT(qq.id) questions FROM quizzes q JOIN quiz_questions qq ON qq.quiz_id=q.id AND qq.activity_type='challenge' AND qq.status='active' WHERE q.status='active' GROUP BY q.lesson_id) x ON x.lesson_id=l.id WHERE g.grade_number IN (6,7,9,10) AND l.status='active' AND l.content_source='textbook' GROUP BY g.grade_number ORDER BY g.grade_number";
foreach($db->query($sql) as $row){$ready=(int)$row['lessons']===(int)$row['notes_ready']&&(int)$row['lessons']===(int)$row['challenges_ready'];echo ($ready?'PASS':'FAIL').": Grade {$row['grade_number']} — {$row['lessons']} lessons, {$row['notes_ready']} notes, {$row['challenges_ready']} five-question challenges.\n";if(!$ready)$failed=true;}
$bad=$db->query("SELECT COUNT(*) total FROM quiz_questions qq JOIN quizzes q ON q.id=qq.quiz_id JOIN lessons l ON l.id=q.lesson_id JOIN grades g ON g.id=l.grade_id WHERE g.grade_number IN (6,7,9,10) AND qq.activity_type='challenge' AND qq.status='active' AND (qq.correct_option NOT IN ('a','b','c','d') OR COALESCE(qq.question_en,qq.question_si,qq.question_ta,'')='' OR COALESCE(qq.option_a_en,qq.option_a_si,qq.option_a_ta,'')='' OR COALESCE(qq.option_b_en,qq.option_b_si,qq.option_b_ta,'')='' OR COALESCE(qq.option_c_en,qq.option_c_si,qq.option_c_ta,'')='' OR COALESCE(qq.option_d_en,qq.option_d_si,qq.option_d_ta,'')='')")->fetch_assoc();if((int)$bad['total']){echo "FAIL: {$bad['total']} incomplete challenge questions.\n";$failed=true;}else echo "PASS: Every challenge question has four options, an answer and lesson text.\n";exit($failed?1:0);
